using System;using System.Drawing;using System.Reflection;using System.Windows.Forms;using System.IO;using System.Linq;
class PresentationTests {
 static void Assert(bool b,string name){if(!b)throw new Exception(name);Console.WriteLine("PASS: "+name);}
 static double L(Color c){Func<double,double> f=x=>x<=.04045?x/12.92:Math.Pow((x+.055)/1.055,2.4);return .2126*f(c.R/255d)+.7152*f(c.G/255d)+.0722*f(c.B/255d);}
 static double Contrast(Color a,Color b){var x=L(a);var y=L(b);return (Math.Max(x,y)+.05)/(Math.Min(x,y)+.05);}
 [STAThread]static int Main(string[] args){try{var path=Path.GetFullPath(args[0]);AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{var p=Path.Combine(Path.GetDirectoryName(path),new AssemblyName(e.Name).Name+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};var assembly=Assembly.LoadFrom(path);var style=assembly.GetType("CodeWalker.ClxnStyle");var flags=BindingFlags.Static|BindingFlags.NonPublic;var dark=style.GetField("Dark",flags);var original=dark.GetValue(null);try{foreach(bool mode in new[]{false,true}){dark.SetValue(null,mode);Func<string,Color> color=n=>(Color)style.GetProperty(n,flags).GetValue(null);Assert(Contrast(color("Text"),color("Surface"))>=7,(mode?"Dark":"Light")+" theme text contrast >= 7:1");Assert(Contrast(color("OnAccent"),color("Accent"))>=7,(mode?"Dark":"Light")+" theme selected-button contrast >= 7:1");using(var form=(Form)Activator.CreateInstance(assembly.GetType("CodeWalker.ClxnHomeForm"),true)){form.CreateControl();form.PerformLayout();Assert(form.Icon!=null,"Branded window icon is available");if(args.Length>1){Directory.CreateDirectory(args[1]);using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(args[1],mode?"home-dark.png":"home-light.png"));}}}}}finally{dark.SetValue(null,original);}using(var source=assembly.GetManifestResourceStream("666clxn.Brand.Logo"))Assert(source!=null&&source.Length>1000,"Original user logo is embedded in executable");using(var icon=Icon.ExtractAssociatedIcon(path))Assert(icon!=null,"Explorer can extract application icon");Console.WriteLine("PRESENTATION TESTS PASSED");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
